{
  "aktywnosci": [
    {
      "tytul": "Zabawa ruchowo-słuchowa „Wiewiórki zbierają zapasy”",
      "opis": "Nauczyciel rozkłada na dywanie obręcze gimnastyczne jako dziuple wiewiórek oraz rozsypuje na środku sali szyszki i kasztany. Dzieci naśladują skaczące wiewiórki w rytm wygrywany przez nauczyciela na tamburynie. Na przerwę w muzyce i hasło „idzie zima!” każde dziecko podnosi jeden leśny skarb i zanosi go do najbliższej dziupli."
    },
    {
      "tytul": "Malowanie jesiennych drzew stemplami z liści",
      "opis": "Nauczyciel rozdaje dzieciom kartki z narysowanym konturem pnia drzewa oraz przygotowuje tacki z gęstą farbą plakatową w kolorach żółtym, czerwonym, pomarańczowym i brązowym. Przedszkolaki pokrywają zebrane wcześniej liście farbą za pomocą pędzli, a następnie odbijają je na kartce, tworząc gęstą, kolorową koronę drzewa. Gotowe prace dzieci odkładają do wyschnięcia na przedszkolną wystawę."
    },
    {
      "tytul": "Ścieżka badawcza i segregowanie darów lasu",
      "opis": "Nauczyciel umieszcza w miskach różne dary jesiennego lasu: gładkie kasztany, chropowate szyszki, małe żołędzie i kruche liście. Dzieci z zasłoniętymi lub zamkniętymi oczami dotykają skarbów, opisują ich fakturę i zgadują, co trzymają w dłoniach. Następnie przedszkolaki segregują wszystkie elementy do oznaczonych pojemników, porównują ich wielkość i wspólnie przeliczają zawartość każdego koszyka."
    }
  ]
}
